import{_ as n,c as i,o as e,ae as s}from"./chunks/framework.BlRNOFgT.js";const p=JSON.parse('{"title":"Latihan Soal: Security & Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"WBD/security-privacy.md","filePath":"WBD/security-privacy.md"}'),t={name:"WBD/security-privacy.md"};function r(l,a,o,u,g,m){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="latihan-soal-security-privacy" tabindex="-1">Latihan Soal: Security &amp; Privacy <a class="header-anchor" href="#latihan-soal-security-privacy" aria-label="Permalink to &quot;Latihan Soal: Security &amp; Privacy&quot;">​</a></h1><h2 id="bagian-1-konsep-dasar-keamanan-cia-triad" tabindex="-1">Bagian 1: Konsep Dasar Keamanan &amp; CIA Triad <a class="header-anchor" href="#bagian-1-konsep-dasar-keamanan-cia-triad" aria-label="Permalink to &quot;Bagian 1: Konsep Dasar Keamanan &amp; CIA Triad&quot;">​</a></h2><p><strong>1. Manakah dari pernyataan berikut yang secara akurat memetakan jenis ancaman (threat) terhadap properti keamanan (CIA Triad) yang dilanggarnya?</strong></p><ul><li>A. Serangan Interception melanggar Confidentiality.</li><li>B. Serangan Modification melanggar Availability.</li><li>C. Serangan Interruption melanggar Availability.</li><li>D. Serangan Fabrication melanggar Integrity.</li><li>E. Serangan Interception melanggar Integrity.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Modification mengubah data, sehingga melanggar Integrity, bukan Availability. Interception adalah penyadapan (akses tidak sah), melanggar Confidentiality. Interruption memutus akses (Availability). Fabrication membuat objek palsu (Integrity).</p></details><hr><p><strong>2. Dalam konteks terminologi keamanan sistem, manakah hubungan sebab-akibat yang BENAR antara Vulnerability, Threat, dan Control?</strong></p><ul><li>A. Control adalah ukuran protektif yang menutup atau meminimalisir Threat.</li><li>B. Vulnerability adalah serangkaian keadaan yang berpotensi menyebabkan kerugian.</li><li>C. Attack terjadi ketika manusia mengeksploitasi Vulnerability.</li><li>D. Control bertujuan untuk mencegah, menghalangi, mengalihkan, mendeteksi, atau memulihkan sistem.</li><li>E. Threat adalah kelemahan intrinsik dalam sistem keamanan yang belum ditambal.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena Control menutup Vulnerability, bukan Threat (Threat adalah faktor eksternal). Opsi B dan E tertukar definisinya: Vulnerability adalah kelemahan (weakness), sedangkan Threat adalah potensi bahaya (circumstances causing loss/harm).</p></details><hr><h2 id="bagian-2-web-security-mechanics-cors-sop-http" tabindex="-1">Bagian 2: Web Security Mechanics (CORS, SOP, HTTP) <a class="header-anchor" href="#bagian-2-web-security-mechanics-cors-sop-http" aria-label="Permalink to &quot;Bagian 2: Web Security Mechanics (CORS, SOP, HTTP)&quot;">​</a></h2><p><strong>3. Mengenai Cross-Origin Resource Sharing (CORS) dan Same-Origin Policy, manakah implikasi teknis yang valid?</strong></p><ul><li>A. Secara default, browser mengizinkan same-origin requests (domain, protokol, dan port yang sama).</li><li>B. CORS adalah mekanisme HTTP header yang memungkinkan server untuk &quot;melonggarkan&quot; aturan Same-Origin Policy.</li><li>C. CORS bertujuan untuk memblokir semua request dari domain eksternal demi keamanan.</li><li>D. Tanpa header CORS yang tepat, Main request (seperti GET image) dari domain berbeda akan selalu gagal di sisi server.</li><li>E. Header CORS dikirim oleh server untuk memberitahu browser origin mana yang diizinkan memuat resource.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong> Opsi C salah total; CORS justru mengizinkan sharing, bukan memblokir (SOP yang memblokir). Opsi D salah karena request mungkin berhasil di server, tapi responnya diblokir oleh browser, atau tergantung tipe request (simple vs preflight).</p></details><hr><p><strong>4. Mengapa Network Layer Security (seperti Firewall dan SSL/TLS) seringkali gagal mencegah serangan pada Application Layer?</strong></p><ul><li>A. Firewall jaringan biasanya hanya memeriksa port dan alamat IP, bukan isi konten trafik HTTP.</li><li>B. SSL/TLS mengenkripsi trafik, sehingga serangan (seperti SQL Injection) di dalam payload justru tidak terbaca oleh IDS jaringan.</li><li>C. Application Layer tidak memiliki perimeter keamanan yang jelas karena kode aplikasi kustom memiliki banyak celah logika.</li><li>D. Network Security tidak bisa membedakan antara request SQL yang valid dan yang berbahaya jika sintaksnya benar secara protokol TCP/IP.</li><li>E. Firewall tidak bisa melakukan Hardening pada sistem operasi.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, D</strong></p><p><strong>Penjelasan:</strong> Semua opsi A-D benar. Opsi E salah karena Hardening OS adalah bagian dari strategi pertahanan lapis infrastruktur yang sering diasosiasikan dengan keamanan jaringan/sistem, namun poin utamanya adalah ketidakmampuan firewall jaringan membaca logic aplikasi.</p></details><hr><h2 id="bagian-3-injection-attacks-sqli-xss" tabindex="-1">Bagian 3: Injection Attacks (SQLi &amp; XSS) <a class="header-anchor" href="#bagian-3-injection-attacks-sqli-xss" aria-label="Permalink to &quot;Bagian 3: Injection Attacks (SQLi &amp; XSS)&quot;">​</a></h2><p><strong>5. Sebuah form login menerima input Account dan SKU. Jika input Account diisi dengan string <code>&#39; OR 1=1 --</code>, manakah pernyataan teknis yang benar mengenai mekanisme serangan ini?</strong></p><ul><li>A. Tanda <code>--</code> berfungsi untuk mengomentari (mengabaikan) sisa perintah SQL asli di belakang input.</li><li>B. Serangan ini bertujuan untuk melakukan Buffer Overflow pada memori database.</li><li>C. Kondisi <code>1=1</code> selalu bernilai True, menyebabkan query mengembalikan semua baris atau baris pertama tabel (biasanya admin).</li><li>D. Ini adalah contoh Cross-Site Scripting karena menggunakan karakter khusus.</li><li>E. Input tersebut memanipulasi struktur logika query SQL yang dieksekusi oleh database.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B salah, ini adalah SQL Injection (SQLi), bukan Buffer Overflow. Opsi D salah, ini SQLi, bukan XSS. XSS melibatkan Javascript, SQLi melibatkan perintah database.</p></details><hr><p><strong>6. Analisis serangan Cross-Site Scripting (XSS). Manakah skenario atau karakteristik yang VALID?</strong></p><ul><li>A. Dalam Stored XSS, skrip berbahaya disimpan di database server dan dieksekusi setiap kali korban memuat halaman tersebut.</li><li>B. Dampak utama XSS adalah penyerang bisa mendapatkan akses penuh ke DOM (Document Object Model) dan cookies korban.</li><li>C. XSS dapat dicegah sepenuhnya dengan menggunakan SSL/HTTPS.</li><li>D. Serangan ini terjadi karena aplikasi gagal memvalidasi atau melakukan encoding pada input pengguna sebelum menampilkannya kembali ke browser.</li><li>E. XSS menyerang database server secara langsung untuk menghapus tabel.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong> Opsi C salah; HTTPS hanya mengenkripsi jalur, tidak mencegah eksekusi skrip jahat di browser. Opsi E salah; XSS adalah serangan client-side, targetnya adalah user/browser, bukan menghapus tabel server (itu SQLi).</p></details><hr><p><strong>7. Diberikan potongan kode respons server berikut:</strong></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Your query for &#39;cookies&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;malicious</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">script&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&#39; returned...&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>Apa kesimpulan keamanan yang dapat ditarik?</strong></p><ul><li>A. Aplikasi rentan terhadap Reflected XSS.</li><li>B. Aplikasi telah melakukan sanitasi input dengan benar.</li><li>C. Browser akan mengeksekusi tag <code>&lt;script&gt;</code> tersebut.</li><li>D. Server secara otomatis memblokir karakter <code>&lt;</code> dan <code>&gt;</code>.</li><li>E. Input pengguna dikembalikan mentah-mentah (echoed back) dalam respon HTTP.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B dan D salah karena tag script tercetak utuh di output, artinya tidak ada sanitasi/encoding, dan browser akan menganggapnya sebagai kode executable.</p></details><hr><h2 id="bagian-4-session-management-authentication" tabindex="-1">Bagian 4: Session Management &amp; Authentication <a class="header-anchor" href="#bagian-4-session-management-authentication" aria-label="Permalink to &quot;Bagian 4: Session Management &amp; Authentication&quot;">​</a></h2><p><strong>8. Mengenai serangan Session Hijacking dan mitigasinya, manakah pernyataan yang benar?</strong></p><ul><li>A. Penyerang harus mengetahui password pengguna untuk melakukan pembajakan sesi.</li><li>B. Session Cookie dapat dicuri melalui XSS atau Network Sniffing (jika tidak dienkripsi).</li><li>C. Menggunakan timeout sesi yang pendek dapat mengurangi jendela waktu eksploitasi jika cookie bocor.</li><li>D. Session Hijacking terjadi ketika pengguna membuat sesi baru tanpa melakukan logout.</li><li>E. Mewajibkan HTTPS membantu mencegah pencurian cookie melalui monitoring trafik jaringan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A salah; inti pembajakan sesi adalah mengambil alih akses tanpa perlu tahu password (cukup session ID). Opsi D salah; itu hanya bad practice, bukan definisi hijacking.</p></details><hr><p><strong>9. Sebuah sistem menerapkan kebijakan: &quot;Kunci akun pengguna setelah 3 kali percobaan login gagal&quot;. Apa implikasi keamanan (trade-off) dari kebijakan ini?</strong></p><ul><li>A. Kebijakan ini efektif mencegah Brute Force Attack secara online.</li><li>B. Kebijakan ini membuka celah untuk serangan Denial of Service (DoS) yang menargetkan user spesifik (Lockout attack).</li><li>C. Kebijakan ini memastikan Non-Repudiation.</li><li>D. Penyerang dapat dengan sengaja memasukkan password salah pada akun korban untuk mencegah pemilik asli masuk.</li><li>E. Kebijakan ini adalah satu-satunya cara mencegah akses database ilegal.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong> Opsi C dan E salah. Trade-off klasik: mencegah brute force (A) tapi memungkinkan penyerang memblokir akses user sah (B, D).</p></details><hr><p><strong>10. Dalam konteks Authentication Factors, manakah pengelompokan yang tepat?</strong></p><ul><li>A. Password dan PIN adalah faktor Knowledge (Sesuatu yang Anda tahu).</li><li>B. Sidik jari (Fingerprint) adalah faktor Possession (Sesuatu yang Anda miliki).</li><li>C. Ponsel atau Token Hardware adalah faktor Possession (Sesuatu yang Anda miliki).</li><li>D. Retina scan adalah faktor Attribute (Sesuatu yang melekat pada Anda/Biometrik).</li><li>E. Jawaban &quot;Nama Gadis Ibu Kandung&quot; adalah faktor Attribute.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B salah, sidik jari adalah Attribute/Biometric, bukan Possession. Opsi E salah, pertanyaan keamanan adalah Knowledge.</p></details><hr><h2 id="bagian-5-authorization-access-control" tabindex="-1">Bagian 5: Authorization &amp; Access Control <a class="header-anchor" href="#bagian-5-authorization-access-control" aria-label="Permalink to &quot;Bagian 5: Authorization &amp; Access Control&quot;">​</a></h2><p><strong>11. Apa perbedaan mendasar antara Authentication dan Authorization?</strong></p><ul><li>A. Authentication memverifikasi &quot;Siapa Anda&quot;, Authorization menentukan &quot;Apa yang boleh Anda lakukan&quot;.</li><li>B. Authentication menggunakan Access Control List (ACL), Authorization menggunakan Password.</li><li>C. Authorization terjadi setelah proses Authentication berhasil.</li><li>D. Authentication menjamin Integrity, Authorization menjamin Availability.</li><li>E. Contoh Authorization adalah izin Read-Only pada folder yang dibagikan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B terbalik. Opsi D tidak relevan secara definisi langsung. AuthN = Identitas, AuthZ = Izin Akses.</p></details><hr><p><strong>12. Bagaimana Access Control Lists (ACLs) bekerja dalam membatasi akses sumber daya?</strong></p><ul><li>A. ACL adalah tabel yang menghubungkan pengguna (user) dengan sumber daya (resources) beserta izin spesifiknya.</li><li>B. Penggunaan grup dalam ACL dapat mengurangi kompleksitas dan ukuran tabel izin secara dramatis.</li><li>C. ACL menggantikan kebutuhan akan Encryption pada file.</li><li>D. ACL mendefinisikan kebijakan akses, misalnya User A boleh membaca File X tapi tidak boleh mengedit.</li><li>E. ACL hanya efektif jika diterapkan di Network Layer.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong> Opsi C salah; enkripsi melindungi kerahasiaan konten, ACL melindungi akses logis. Opsi E salah; ACL justru fundamental di sistem operasi dan aplikasi (Application Layer).</p></details><hr><h2 id="bagian-6-privacy-data-protection" tabindex="-1">Bagian 6: Privacy &amp; Data Protection <a class="header-anchor" href="#bagian-6-privacy-data-protection" aria-label="Permalink to &quot;Bagian 6: Privacy &amp; Data Protection&quot;">​</a></h2><p><strong>13. Berdasarkan prinsip perlindungan data (Data Protection Principles), manakah tindakan yang dianggap melanggar prinsip Data Lifetime dan Purpose?</strong></p><ul><li>A. Menyimpan data pelanggan selamanya meskipun akun mereka sudah dihapus.</li><li>B. Menggunakan data nomor telepon yang dikumpulkan untuk verifikasi keamanan (2FA) sebagai target iklan marketing tanpa izin.</li><li>C. Memberikan fitur bagi pengguna untuk mengunduh dan memperbaiki data pribadi mereka.</li><li>D. Mengenkripsi data sensitif saat disimpan di database.</li><li>E. Menghapus data pribadi segera setelah tujuan pengumpulannya tercapai.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B</strong></p><p><strong>Penjelasan:</strong> Opsi A melanggar prinsip Data Lifetime (jangan simpan lebih lama dari kebutuhan). Opsi B melanggar prinsip Purpose (tujuan penggunaan data harus spesifik dan ditaati). C, D, E adalah praktik yang benar (Good Practice).</p></details><hr><p><strong>14. Prinsip Awareness and Control dalam privasi menuntut pengembang aplikasi untuk:</strong></p><ul><li>A. Menyembunyikan detail teknis pengumpulan data agar user tidak bingung.</li><li>B. Memberitahu pengguna data apa saja yang dikumpulkan saat menggunakan produk.</li><li>C. Memberikan kendali kepada pengguna atas informasi pribadi yang dikumpulkan.</li><li>D. Meminta persetujuan (Consent) sebelum mengungkapkan data ke pihak ketiga.</li><li>E. Menyimpan data di negara dengan hukum perlindungan data yang paling lemah untuk efisiensi biaya.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A melanggar transparansi. Opsi E melanggar prinsip Location (harus di negara dengan perlindungan setara atau kuat).</p></details><hr><h2 id="bagian-7-security-controls-defense-strategy" tabindex="-1">Bagian 7: Security Controls &amp; Defense Strategy <a class="header-anchor" href="#bagian-7-security-controls-defense-strategy" aria-label="Permalink to &quot;Bagian 7: Security Controls &amp; Defense Strategy&quot;">​</a></h2><p><strong>15. Manakah dari berikut ini yang termasuk dalam kategori Security Control tipe &quot;Prevent&quot; (Mencegah) dan &quot;Detect&quot; (Mendeteksi)?</strong></p><ul><li>A. Menggunakan HTTPS untuk mencegah penyadapan session cookie.</li><li>B. Menganalisis log trafik untuk mengidentifikasi pola serangan brute force.</li><li>C. Melakukan backup database untuk memulihkan data setelah serangan Ransomware.</li><li>D. Menutup celah kerentanan (patching vulnerability) pada kode aplikasi.</li><li>E. Memindahkan target serangan ke server Honeypot (Deflect).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong> Opsi A dan D adalah pencegahan (Prevent). Opsi B adalah deteksi (Detect). Opsi C adalah pemulihan (Recover), dan Opsi E adalah pengalihan (Deflect).</p></details><hr><p><strong>16. Mengapa Input Validation dianggap sebagai pertahanan krusial dalam keamanan aplikasi web?</strong></p><ul><li>A. Dapat mencegah serangan Injection (SQLi) dengan menolak karakter berbahaya.</li><li>B. Dapat mencegah XSS dengan memastikan input tidak mengandung tag HTML yang dapat dieksekusi.</li><li>C. Input validation menggantikan kebutuhan akan autentikasi user.</li><li>D. Validasi harus dilakukan di sisi klien (browser) saja agar server tidak terbebani.</li><li>E. Merupakan kontrol utama untuk memastikan data yang masuk ke sistem sesuai dengan format yang diharapkan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong> Opsi C salah. Opsi D sangat berbahaya; validasi wajib dilakukan di server karena validasi klien bisa dilewati (bypassed) dengan mudah oleh penyerang.</p></details><hr><h2 id="bagian-8-owasp-top-10-trends" tabindex="-1">Bagian 8: OWASP Top 10 Trends <a class="header-anchor" href="#bagian-8-owasp-top-10-trends" aria-label="Permalink to &quot;Bagian 8: OWASP Top 10 Trends&quot;">​</a></h2><p><strong>17. Melihat evolusi OWASP Top 10 dari 2017 ke 2021, perubahan manakah yang signifikan dan mencerminkan pergeseran tren keamanan modern?</strong></p><ul><li>A. Injection turun peringkat (bukan lagi nomor 1) digantikan oleh Broken Access Control.</li><li>B. Insecure Design diperkenalkan sebagai kategori baru pada tahun 2021.</li><li>C. Server-Side Request Forgery (SSRF) dihapus dari daftar karena sudah jarang terjadi.</li><li>D. Cryptographic Failures (sebelumnya Sensitive Data Exposure) naik peringkat menjadi ancaman utama (urutan ke-2).</li><li>E. Cross-Site Scripting (XSS) dipisahkan menjadi kategori sendiri yang lebih besar di 2021.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong> Opsi C salah, SSRF justru baru masuk di 2021. Opsi E salah, XSS justru digabung ke dalam kategori Injection di 2021, tidak berdiri sendiri lagi seperti di 2017.</p></details><hr><p><strong>18. Kategori Using Components with Known Vulnerabilities (Menggunakan Komponen dengan Kerentanan yang Diketahui) menyiratkan risiko apa?</strong></p><ul><li>A. Risiko menggunakan library pihak ketiga yang belum di-update.</li><li>B. Bahaya menggunakan sistem operasi bajakan.</li><li>C. Risiko keamanan pada supply chain perangkat lunak.</li><li>D. Risiko yang timbul karena menulis kode SQL manual daripada menggunakan ORM.</li><li>E. Pentingnya memantau CVE (Common Vulnerabilities and Exposures) terkait dependensi aplikasi.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B terlalu umum dan biasanya terkait lisensi/legal meski berisiko. Opsi D berkaitan dengan Injection, bukan komponen rentan. Poin kuncinya adalah library/dependency eksternal.</p></details><hr><h2 id="bagian-9-advanced-technical-scenarios" tabindex="-1">Bagian 9: Advanced Technical Scenarios <a class="header-anchor" href="#bagian-9-advanced-technical-scenarios" aria-label="Permalink to &quot;Bagian 9: Advanced Technical Scenarios&quot;">​</a></h2><p><strong>19. Jika sebuah aplikasi web mengizinkan user mengupload file gambar, namun tidak memvalidasi konten filenya, serangan apa yang mungkin terjadi?</strong></p><ul><li>A. Penyerang mengupload file PHP/Shell yang menyamar sebagai gambar untuk mendapatkan Remote Code Execution.</li><li>B. Penyerang melakukan SQL Injection melalui nama file.</li><li>C. Stored XSS jika nama file ditampilkan kembali tanpa escaping.</li><li>D. Man-in-the-Middle Attack pada koneksi server.</li><li>E. Server akan otomatis terenkripsi oleh Ransomware.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C</strong></p><p><strong>Penjelasan:</strong> Opsi A adalah risiko terbesar (Unrestricted File Upload). B dan C mungkin terjadi melalui metadata file (nama file). D dan E bukan dampak langsung dari upload file tanpa validasi (E butuh eksekusi, D butuh akses jaringan).</p></details><hr><p><strong>20. Brute Force Attacks tidak hanya sekadar menebak password secara acak. Metode apa lagi yang sering digunakan penyerang dalam kategori ini?</strong></p><ul><li>A. Dictionary Attack: Menggunakan daftar kata umum atau password populer yang pernah bocor.</li><li>B. Menggunakan Rainbow Tables untuk membalikkan hash password yang dicuri.</li><li>C. Mencoba kombinasi username yang valid (hasil enumeration) dengan password lemah.</li><li>D. Menggunakan teknik Phishing untuk meminta password langsung.</li><li>E. Memanfaatkan fakta bahwa banyak pengguna menggunakan password yang mudah diingat.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B adalah serangan offline terhadap database password (cracking), bukan serangan brute force aktif ke form login web. Opsi D adalah Social Engineering, bukan Brute Force teknis.</p></details>',91)])])}const d=n(t,[["render",r]]);export{p as __pageData,d as default};
